import re


def predict(board_lines, action):
    """Predict a complete 64x64 board without external or persistent state."""
    board = [list(row) for row in board_lines]

    # Accept the displayed action syntax, plus simple tuple representations.
    mouse = None
    if isinstance(action, str):
        name = action.strip().upper()
        if name.startswith("MOUSE"):
            values = re.findall(r"-?\d+", name)
            if len(values) >= 2:
                mouse = (int(values[0]), int(values[1]))
            name = "MOUSE"
    elif isinstance(action, (tuple, list)) and action:
        name = str(action[0]).upper()
        if name == "MOUSE":
            if len(action) >= 3:
                mouse = (int(action[1]), int(action[2]))
            elif len(action) == 2 and isinstance(action[1], (tuple, list)):
                mouse = tuple(map(int, action[1][:2]))
    else:
        name = str(action).upper()

    # Every demonstrated action consumes one status-strip pixel.
    for c in range(64):
        if board[63][c] == "W":
            board[63][c] = "p"
            break

    removed = False

    if name == "MOUSE" and mouse is not None:
        mr, mc = mouse
        if 0 <= mr < 63 and 0 <= mc < 64:
            top = (mr // 6) * 6 + 1
            left = (mc // 6) * 6 + 1

            if top + 4 < 63 and left + 4 < 64:
                is_green = any(
                    board[r][c] == "N"
                    for r in range(top, top + 5)
                    for c in range(left, left + 5)
                )
                if is_green:
                    removed = True
                    for r in range(top, top + 5):
                        for c in range(left, left + 5):
                            board[r][c] = "S"

                    # Remove shared horizontal borders with open neighbors.
                    for border, neighbor in (
                        (top - 1, top - 2),
                        (top + 5, top + 6),
                    ):
                        if 0 <= neighbor < 63 and 0 <= border < 63:
                            if all(
                                board[neighbor][c] == "S"
                                for c in range(left, left + 5)
                            ):
                                for c in range(left, left + 5):
                                    board[border][c] = "S"

                    # Remove shared vertical borders with open neighbors.
                    for border, neighbor in (
                        (left - 1, left - 2),
                        (left + 5, left + 6),
                    ):
                        if 0 <= neighbor < 64 and 0 <= border < 64:
                            if all(
                                board[r][neighbor] == "S"
                                for r in range(top, top + 5)
                            ):
                                for r in range(top, top + 5):
                                    board[r][border] = "S"

                    # An intersection opens when all four adjoining interiors
                    # are open.
                    for r in (top - 1, top + 5):
                        for c in (left - 1, left + 5):
                            if 0 < r < 62 and 0 < c < 63:
                                if all(
                                    board[r + dr][c + dc] == "S"
                                    for dr in (-1, 1)
                                    for dc in (-1, 1)
                                ):
                                    board[r][c] = "S"

    if name not in ("LEFT", "RIGHT") and not removed:
        return ["".join(row) for row in board]

    # The topmost blue pixel is the horizontal center of the sprite.
    player = None
    for r in range(63):
        for c in range(64):
            if board[r][c] == "b":
                player = (r, c - 2)
                break
        if player is not None:
            break

    if player is None:
        return ["".join(row) for row in board]

    py, px = player
    if not (0 <= px <= 59 and 0 <= py <= 58):
        return ["".join(row) for row in board]

    facing = "LEFT" if board[py + 1][px + 1] == "Y" else "RIGHT"
    if name in ("LEFT", "RIGHT"):
        facing = name

    # Erase the complete sprite footprint, including its transparent corners.
    for r in range(py, py + 5):
        for c in range(px, px + 5):
            board[r][c] = "S"

    def open_rectangle(top, left, height=5, width=5):
        return (
            0 <= top
            and top + height <= 63
            and 0 <= left
            and left + width <= 64
            and all(
                board[r][c] == "S"
                for r in range(top, top + height)
                for c in range(left, left + width)
            )
        )

    if name in ("LEFT", "RIGHT"):
        dx = -6 if name == "LEFT" else 6
        target = px + dx
        # Include the separator crossed between the two tile interiors.
        path_left = target if dx < 0 else px + 5
        if open_rectangle(py, path_left, 5, 6):
            px = target

    original_y = py
    while py >= 6 and open_rectangle(py - 6, px, 6, 5):
        py -= 6

    def wall_pixel(r, c):
        phase = r % 6
        gray = (
            (phase == 1 and c % 6 == 2)
            or (phase == 4 and c % 6 == 1)
            or (phase == 5 and c % 6 == 4)
        )
        return "G" if gray else "B"

    def hidden_row(world_r):
        """Extrapolated terrain immediately above the initial viewport."""
        row = [wall_pixel(world_r, c) for c in range(64)]

        if world_r < -12:
            for c in range(13, 54):
                row[c] = "S"
            return row

        phase = world_r % 6

        # Three adjacent green columns, in the two newly exposed tile rows.
        if phase != 0:
            for left in (13, 19, 25):
                for dc in range(5):
                    corner = phase in (1, 5) and dc in (0, 4)
                    row[left + dc] = "G" if corner else "N"

        # The lower newly exposed tile row is open on the right.
        if -6 < world_r < 0:
            for c in range(31, 54):
                row[c] = "S"

        return row

    rise = original_y - py
    if rise:
        terrain = [row[:] for row in board[:63]]
        for r in range(63):
            source = r - rise
            board[r] = (
                terrain[source][:]
                if source >= 0
                else hidden_row(source)
            )
        py += rise

    sprite = (
        ("BBbBB", "BYbbB", "BYbbB", "BBbBB", "SBBBS")
        if facing == "LEFT"
        else ("BBbBB", "BbbYB", "BbbYB", "BBbBB", "SBBBS")
    )
    for dr, line in enumerate(sprite):
        for dc, color in enumerate(line):
            board[py + dr][px + dc] = color

    return ["".join(row) for row in board]

